INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q13190', 'Battle of Bolia', 'The Battle of Bolia took place in 468 between the Ostrogoths led by the Amal dynasty and a coalition of other former allies of Attila. It took place in or near the Roman province of Pannonia.', 469, NULL, NULL, NULL, NULL, NULL, 'year', '469', 47, 'https://en.wikipedia.org/wiki/Battle_of_Bolia'),
  ('Q938980', 'Battle of Ménfő', 'The Battle of Ménfő was an important battle in the early history of the Kingdom of Hungary. Fought in 1044 at Ménfő, near Győr, between an army of mostly Germans and Hungarians (Magyars), it was a victory for the Germans and thus for Westernising influences in Hungary.', 1044, 7, 6, NULL, NULL, NULL, 'day', '6 July 1044', 50, 'https://en.wikipedia.org/wiki/Battle_of_M%C3%A9nf%C5%91'),
  ('Q705874', 'Battle of Mohi', 'The Battle of Mohi (11 April 1241) was a pivotal conflict between the Mongol Empire and the Kingdom of Hungary during the Mongol invasion of Europe. The battle took place at Muhi (then Mohi), a town located in present-day Hungary, southwest of the Sajó River.', 1241, 4, 11, NULL, NULL, NULL, 'day', '11 April 1241', 70, 'https://en.wikipedia.org/wiki/Battle_of_Mohi'),
  ('Q446410', 'Battle of the Leitha River', 'The Battle of the Leitha River was fought on 15 June 1246 near the banks of the Leitha river between the forces of the King Béla IV of Hungary and Duke Frederick II of Austria. The Hungarian army was routed, but Duke Frederick was killed, ending Austrian claims to the western counties of Hungary.', 1246, 6, 15, NULL, NULL, NULL, 'day', '15 June 1246', 50, 'https://en.wikipedia.org/wiki/Battle_of_the_Leitha_River'),
  ('Q1057681', 'Battle of Lake Hód', 'The Battle of Lake Hód (Hungarian: Hód-tavi csata) was fought between the Kingdom of Hungary and the Cumans in September or October 1282. King Ladislaus IV of Hungary successfully repelled the invaders.', 1282, NULL, NULL, NULL, NULL, NULL, 'year', '1282', 39, 'https://en.wikipedia.org/wiki/Battle_of_Lake_H%C3%B3d'),
  ('Q178510', 'Battle of Mohács', 'The Battle of Mohács took place on 29 August 1526 near Mohács, in the Kingdom of Hungary. It was fought between the forces of Hungary, led by King Louis II, and the invading Ottoman Empire, commanded by Suleiman the Magnificent and his grand vizier, Pargalı Ibrahim Pasha.', 1526, 8, 29, NULL, NULL, NULL, 'day', '29 August 1526', 80, 'https://en.wikipedia.org/wiki/Battle_of_Moh%C3%A1cs'),
  ('Q1049956', 'Hungarian campaign of 1527–1528', 'The Hungarian Civil War (Hungarian: magyar belháború) or campaign of 1527–1528 was launched by Ferdinand I, Archduke of Austria and King of Hungary and Bohemia and his Hungarian followers against the Ottoman Turks. Following the Battle of Mohács, the Ottomans were forced to withdraw as events elsewhere in their now massive Empire required the Sultan''s attention.', 1527, NULL, NULL, 1528, NULL, NULL, 'year', '1527–1528', 56, 'https://en.wikipedia.org/wiki/Hungarian_campaign_of_1527%E2%80%931528'),
  ('Q4207617', 'Balkan campaign of 1529', 'Suleiman I''s campaign of 1529 was launched by the Ottoman Empire to take the Austrian capital Vienna and thereby strike a decisive blow, allowing the Ottomans to consolidate their hold on Hungary. This was in response to Ferdinand I''s daring assault on Ottoman Hungary.', 1529, NULL, NULL, NULL, NULL, NULL, 'year', '1529', 47, 'https://en.wikipedia.org/wiki/Suleiman_I''s_campaign_of_1529'),
  ('Q25466274', 'Siege of Buda', 'The siege of Buda was a military operation led by the Ottoman Empire with the aim of capturing Buda and installing John Zápolya as its ruler. Ferdinand I was able to defeat John Zápolya in September 1527 and have himself crowned in November.', 1529, NULL, NULL, 1529, 9, 8, 'year', '1529', 39, 'https://en.wikipedia.org/wiki/Siege_of_Buda_(1529)'),
  ('Q673641', 'Siege of Güns', 'The siege of Kőszeg (Hungarian: Kőszeg ostroma) or siege of Güns (Turkish: Güns Kuşatması), also known as the German campaign (Turkish: Alman Seferi) was a siege of Kőszeg (German: Güns) in the Western Kingdom of Hungary which ruled by Ferdinand I, a Habsburg king, that took place in 1532. During the siege, the defending forces of the Habsburg monarchy under the leadership of Croatian Captain Nikola Jurišić (Hungarian: Jurisics Miklós), defended the small border fort of Kőszeg with fewer than 50 soldiers and only 700 Hungarian villagers, with no cannons and few guns.', 1532, 8, 5, 1532, 8, 30, 'day', '5 August 1532 – 30 August 1532', 59, 'https://en.wikipedia.org/wiki/Siege_of_K%C5%91szeg'),
  ('Q622844', 'Treaty of Nagyvárad', 'The Treaty of Nagyvárad (or Treaty of Grosswardein) was a secret peace agreement between Emperor Ferdinand I and John Zápolya, rival claimants to the Kingdom of Hungary, signed in Grosswardein / Várad (modern-day Oradea, Romania) on February 24, 1538. In the treaty, they divided Hungary between them according to the actual possession.', 1540, 2, 24, NULL, NULL, NULL, 'day', '24 February 1540', 55, 'https://en.wikipedia.org/wiki/Treaty_of_Nagyv%C3%A1rad'),
  ('Q604587', 'Siege of Buda', 'The siege of Buda (4 May – 21 August 1541) ended with the capture of the city of Buda, the historical capital of the Kingdom of Hungary, by the Ottoman Empire, leading to about 150 years of Ottoman rule in parts of Hungary. The siege, part of the Little War in Hungary, was one of the most important Ottoman victories over the Habsburg monarchy during Ottoman–Habsburg wars (16th to 18th century) in Hungary and the Balkans.', 1541, 8, 21, 1541, 8, 21, 'day', '21 August 1541', 55, 'https://en.wikipedia.org/wiki/Siege_of_Buda_(1541)'),
  ('Q850771', 'Siege of Pest', 'The siege of Pest (modern city of Budapest, Hungary) occurred in 1542, when Ferdinand I attempted to recover the cities of Buda and Pest in 1542 from the Ottoman Empire. They had been occupied by the Ottomans under Suleiman since the siege of Buda (1541).', 1542, NULL, NULL, 1542, 10, 9, 'year', '1542', 39, 'https://en.wikipedia.org/wiki/Siege_of_Pest'),
  ('Q4207737', 'Siege of Esztergom', 'The siege of Esztergom occurred between 25 July and 10 August 1543, when the Ottoman army, led by Sultan Suleiman the Magnificent, besieged the city of Esztergom in modern Hungary. The city was captured by the Ottomans after two weeks.', 1543, 8, 10, 1543, 8, 10, 'day', '10 August 1543', 50, 'https://en.wikipedia.org/wiki/Siege_of_Esztergom_(1543)'),
  ('Q3321519', '1552 Siege of Eger', 'The siege of Eger (Hungarian: Eger ostroma) occurred during the 16th century Ottoman wars in Europe. In 1552, the forces of the Ottoman Empire led by Kara Ahmed Pasha laid siege to the Castle of Eger, located in the northern part of the Kingdom of Hungary, but the defenders led by István Dobó repelled the attacks and defended the castle, despite being outnumbered approximately 17 to 1.', 1552, NULL, NULL, 1552, 10, 17, 'year', '1552', 57, 'https://en.wikipedia.org/wiki/Siege_of_Eger_(1552)'),
  ('Q606621', 'Siege of Szigetvár', 'The siege of Szigetvár or the Battle of Szigeth (pronunciation: [ˈsiɡɛtvaːr]; Hungarian: Szigetvár ostroma; Croatian: Bitka kod Sigeta, Sigetska bitka; Turkish: Zigetvar Kuşatması) was an Ottoman siege of the fortress of Szigetvár in the Kingdom of Hungary. The fort had blocked Sultan Suleiman''s line of advance towards Vienna in 1566.', 1566, 8, 6, 1566, 9, 8, 'day', '6 August 1566 – 8 September 1566', 67, 'https://en.wikipedia.org/wiki/Siege_of_Szigetv%C3%A1r'),
  ('Q690361', 'Long War', 'The Long Turkish War, or Thirteen Years'' War, was an indecisive land war between the Holy Roman Empire (primarily the Habsburg monarchy) and the Ottoman Empire, primarily over the principalities of Wallachia, Transylvania, and Moldavia. It was waged from 1593 to 1606, but in Europe, especially in Hungary, it is called the Fifteen Years'' War (Hungarian: tizenöt éves háború), reckoning from the 1591–1592 Turkish campaign that captured Bihać in the Kingdom of Croatia.', 1593, 7, 29, 1606, 11, 11, 'day', '29 July 1593 – 11 November 1606', 68, 'https://en.wikipedia.org/wiki/Long_Turkish_War'),
  ('Q690495', 'Battle of Keresztes', 'The Battle of Keresztes (also known as the Battle of Mezőkeresztes) (Turkish: Haçova Muharebesi) took place on 24–26 October 1596. It was fought between a combined Habsburg-Transylvanian force and the Ottoman Empire near the village of Mezőkeresztes (Turkish: Haçova) in modern-day northern Hungary.', 1596, NULL, NULL, 1596, 10, 26, 'year', '1596', 57, 'https://en.wikipedia.org/wiki/Battle_of_Keresztes'),
  ('Q1582631', '1596 Siege of Eger', 'The Ottomans laid siege to the city of Eger (Turkish: Eğri), that lasted from September 20 to October 12, 1596, as part of the Long War, successfully conquering it after the 7,000 defenders of the fortress, mostly foreign mercenaries, were killed by the Ottoman forces commanded by the Sultan Mehmed III himself, who had arrived with the main Ottoman Army from Constantinople.', 1596, NULL, NULL, 1596, 10, 12, 'year', '1596', 41, 'https://en.wikipedia.org/wiki/Siege_of_Eger_(1596)'),
  ('Q4822495', 'Siege of Nagykanizsa', 'During the siege of Nagykanizsa (Turkish: Kanije Savunması, lit. ''The Defence of Kanizsa'') in 1601, a small Ottoman force held the fortress of Naģykanizsa in western Hungary against a much larger coalition army of the Habsburg monarchy, while inflicting heavy losses on its besiegers. This battle was part of the Long War between the Ottoman Empire and the House of Habsburg, lasting from 1593 to 1606.', 1601, 9, 9, 1601, 11, 18, 'day', '9 September 1601 – 18 November 1601', 41, 'https://en.wikipedia.org/wiki/Siege_of_Kanizsa_(1601)'),
  ('Q27673363', 'Siege of Buda', 'The siege of Buda took place in 1603 during the Long Turkish War and was the third and last attempt to capture the town by the Habsburgs; however, despite initial success achieved by the Habsburgs, the Ottomans later thwarted the Habsburg attempt to capture the town.', 1603, NULL, NULL, 1603, 11, 20, 'year', '1603', 34, 'https://en.wikipedia.org/wiki/Siege_of_Buda_(1603)'),
  ('Q170113', 'Battle of Saint Gotthard', 'The Battle of Saint Gotthard (Turkish: Saint Gotthard Muharebesi; German: Schlacht bei St. Gotthard; Hungarian: Szentgotthárdi csata), of the Austro-Turkish War (1663–1664), took place on 1 August 1664 on the Raab between Mogersdorf and the Cistercian monastery St.', 1664, 8, 1, NULL, NULL, NULL, 'day', '1 August 1664', 66, 'https://en.wikipedia.org/wiki/Battle_of_Saint_Gotthard_(1664)'),
  ('Q14566201', 'Siege of Novi Zrin', 'The siege of Novi Zrin (New Zrin Castle); Croatian: Utvrda Novi Zrin; Hungarian: Új-Zrínyivár; Turkish: Zerinvar) in June/July 1664 was last of the military conflicts between the Croatian forces (with allies) led by Nikola Zrinski, Ban (viceroy) of Croatia, and the Ottoman army commanded by Köprülü Fazıl Ahmed Pasha, Grand Vizier, dealing with possession of Novi Zrin Castle, defended by Croats, situated on the bank and marshy islands of Mura River, near the border line between northern Croatia and southwestern part of Hungary, at the time occupied by the Ottomans. The battle resulted in…', 1664, 6, 5, 1664, 7, 7, 'day', '5 June 1664 – 7 July 1664', 41, 'https://en.wikipedia.org/wiki/Siege_of_Novi_Zrin_(1664)'),
  ('Q3625456', 'Siege of Buda', 'The siege of Buda (14 July – 30 October 1684) was a siege by the Holy Roman Empire of the Ottoman fortress of Buda. After 109 days, the siege was abandoned.', 1684, 6, 16, 1684, 10, 30, 'day', '16 June 1684 – 30 October 1684', 48, 'https://en.wikipedia.org/wiki/Siege_of_Buda_(1684)'),
  ('Q4872699', 'Battle of Vác', 'The Battle of Vác was fought on June 27, 1684, near the city of Vác in central Hungary, between the forces of the Ottoman Empire, and the forces of the Holy Roman Empire as part of the Great Turkish War. The Austrian army was victorious.', 1684, 6, 27, NULL, NULL, NULL, 'day', '27 June 1684', 47, 'https://en.wikipedia.org/wiki/Battle_of_V%C3%A1c_(1684)'),
  ('Q697654', 'Battle of Buda', 'The siege of Buda (Hungarian: Buda visszafoglalása, lit. ''Recapture of Buda'') was a military engagement during the Great Turkish War, in which forces of the Holy League, led by the Habsburg Monarchy, recaptured the fortified city of Buda (now part of modern-day Budapest) from the Ottoman Empire. The siege took place between 18 June and 9 September 1686, ending nearly 150 years of Ottoman sovereignty over the former Hungarian capital.', 1686, NULL, NULL, 1686, 9, 2, 'year', '1686', 60, 'https://en.wikipedia.org/wiki/Siege_of_Buda_(1686)'),
  ('Q7483226', 'Siege of Pécs', 'The siege of Pécs was fought from 14 to 22 October 1686, in the city of Pécs in southwestern Hungary, between the armies of the Ottoman Empire and of the Holy Roman Empire. After the castle of Buda was wrested from Ottoman rule in 1686, the Austrian army advanced to capture Pécs which was defended by Sarı Süleyman Pasha.', 1686, 10, 14, 1686, 10, 22, 'day', '14 October 1686 – 22 October 1686', 37, 'https://en.wikipedia.org/wiki/Siege_of_P%C3%A9cs_(1686)'),
  ('Q690470', 'Battle of Mohács', 'The Second Battle of Mohács, also known as the Battle of Harsány Mountain, was fought on 12 August 1687 between the forces of Ottoman Sultan Mehmed IV, commanded by the Grand Vizier Sarı Süleyman Pasha, and the forces of Leopold I, Holy Roman Emperor, commanded by Charles of Lorraine. The result was a decisive victory for the Austrians.', 1687, 8, 12, NULL, NULL, NULL, 'day', '12 August 1687', 68, 'https://en.wikipedia.org/wiki/Battle_of_Moh%C3%A1cs_(1687)'),
  ('Q16858564', 'Battle of Koroncó', 'The Battle of Koroncó took place on 13 June 1704 at Koroncó in Győr County, Hungary between the Kurucs (Hungarians) and the army of Habsburg Empire (Germans, Danes, Serbs, Croats). The Kuruc army was defeated in the battle.', 1704, 6, 13, NULL, NULL, NULL, 'day', '13 June 1704', 34, 'https://en.wikipedia.org/wiki/Battle_of_Koronc%C3%B3'),
  ('Q473716', 'Hungarian Revolution of 1848', 'The Hungarian Revolution of 1848, also known in Hungary as Hungarian Revolution and War of Independence of 1848–1849 (Hungarian: 1848–49-es forradalom és szabadságharc) was one of a number of European Revolutions of 1848 and was closely linked to other revolutions of 1848 in the Habsburg areas. Although the Hungarian War of Independence failed, it is one of the most significant events in Hungary''s modern history, forming the cornerstone of modern Hungarian national identity—the anniversary of the Revolution''s outbreak, 15 March, is one of Hungary''s three national holidays.', 1848, NULL, NULL, 1849, 10, 4, 'year', '1848 – 4 October 1849', 77, 'https://en.wikipedia.org/wiki/Hungarian_Revolution_of_1848'),
  ('Q508298', 'Battle of Mór', 'The Battle of Mór took place during the Hungarian Revolution of 1848 on 30 December 1848 between Austria and Hungarian Revolutionary Army. The Austrians were led by Croatian Ban Lieutenant General Josip Jelačić, while the Hungarians were led by Major General Mór Perczel.', 1848, 12, 30, NULL, NULL, NULL, 'day', '30 December 1848', 34, 'https://en.wikipedia.org/wiki/Battle_of_M%C3%B3r'),
  ('Q1241936', 'Battle of Pákozd', 'The Battle of Pákozd (or Battle of Sukoró) was a battle in the Hungarian war of Independence of 1848–1849, fought on the 29 September 1848 in the Pákozd – Sukoró – Pátka triangle. It was the first and one of the most important major battles of the war of independence, in which the Hungarian revolutionary army led by Lieutenant-General János Móga stopped the troops of the Croatian Ban Josip Jelačić, who, in accordance with the Habsburg plans, was marching towards Pest to occupy it and chase out the Hungarian national government.', 1848, 9, 29, NULL, NULL, NULL, 'day', '29 September 1848', 45, 'https://en.wikipedia.org/wiki/Battle_of_P%C3%A1kozd'),
  ('Q769356', 'Battle of Kápolna', 'The Battle of Kápolna was one of the decisive battles of the Hungarian war of Independence of 1848–1849, fought on 26 and 27 February 1849 between the Hungarian revolutionary army led by Lieutenant General Henryk Dembiński and the Austrian main army operating in Hungary Field Marshal Alfred I, Prince of Windisch-Grätz. After the Austrian offensive from the winter of 1848–1849, which resulted in losing the Western part of the country, the Hungarian army tried its first major counter-attack, but due to the disastrous leadership of the Polish Henryk Dembiński, the battle ended with an Austrian…', 1849, 2, 26, 1849, 2, 27, 'day', '26 February 1849 – 27 February 1849', 39, 'https://en.wikipedia.org/wiki/Battle_of_K%C3%A1polna'),
  ('Q850778', 'Siege of Buda', 'The siege of Buda took place at Buda castle (called Festung Ofen in German), part of the twin capital cities of the Kingdom of Hungary. The Hungarian revolutionary army was led by General Artúr Görgei during the Hungarian War of Independence.', 1849, 5, 4, 1849, 5, 21, 'day', '4 May 1849 – 21 May 1849', 43, 'https://en.wikipedia.org/wiki/Siege_of_Buda_(1849)'),
  ('Q1006312', 'Hungarian Declaration of Independence', 'The Hungarian Declaration of Independence declared the independence of Hungary from the Habsburg Dynasty during the Hungarian Revolution of 1848. The Declaration of Independence severed Hungary’s dynastic allegiance to the House of Habsburg-Lorraine and dissolved the personal union linking the Kingdom of Hungary to the other Habsburg realms.', 1849, 4, 13, NULL, NULL, NULL, 'day', '13 April 1849', 37, 'https://en.wikipedia.org/wiki/Hungarian_Declaration_of_Independence'),
  ('Q27958332', 'First Battle of Komárom', 'The First battle of Komárom was one of the most important battles of the Hungarian War of Independence, fought on 26 April 1849, between the Hungarian and the Austrian Imperial main armies, which some consider ended as a Hungarian victory, while others say that actually it was undecided. This battle was part of the Hungarian Spring Campaign.', 1849, 4, 26, NULL, NULL, NULL, 'day', '26 April 1849', 34, 'https://en.wikipedia.org/wiki/First_Battle_of_Kom%C3%A1rom_(1849)'),
  ('Q56101066', 'Battle of Szolnok', 'The Second Battle of Szolnok took place during the Hungarian war of Independence of 1848–1849 on 5 March 1849. It was fought between the two divisions of the revolutionary Hungarian army led by Major-General János Damjanich and Major-General Károly Vécsey against the brigades of the Austrian Empire led by Major General Leopold Edler von Karger and General Ferenc Ottinger.', 1849, 3, 5, NULL, NULL, NULL, 'day', '5 March 1849', 34, 'https://en.wikipedia.org/wiki/Second_Battle_of_Szolnok'),
  ('Q1747429', 'Hungarian-Czechoslovak-România War', 'The Hungarian–Czechoslovak War, also known as the War for Upper Hungary (Hungarian: Háború Felső-Magyarországért), was a military conflict between the Czechoslovakia and Hungary. It lasted from November 1918 to August 1919.', 1918, 12, NULL, 1919, 6, NULL, 'month', 'December 1918 – June 1919', 47, 'https://en.wikipedia.org/wiki/Hungarian%E2%80%93Czechoslovak_War'),
  ('Q252298', 'Hungarian–Romanian War', 'The Hungarian–Romanian War (Hungarian: magyar–román háború; Romanian: războiul româno-ungar) was fought between Hungary and Romania from 13 November 1918 to 3 August 1919. The conflict had a complex background, with often contradictory motivations for the parties involved.', 1919, 8, 3, 1920, 3, NULL, 'day', '3 August 1919 – March 1920', 63, 'https://en.wikipedia.org/wiki/Hungarian%E2%80%93Romanian_War'),
  ('Q902242', 'White Terror', 'The White Terror (Hungarian: Fehér Terror) was a two-year period (1919–1921) of repressive violence in Hungary carried out by counter-revolutionary soldiers against the real and alleged supporters of the short-lived Hungarian Soviet Republic and its Red Terror, especially against the Jews perceived as its main supporters. Tens of thousands were imprisoned without trial.', 1919, NULL, NULL, 1921, NULL, NULL, 'year', '1919–1921', 60, 'https://en.wikipedia.org/wiki/White_Terror_(Hungary)'),
  ('Q181902', 'Treaty of Trianon', 'The Treaty of Trianon (French: Traité de Trianon; Hungarian: Trianoni békediktátum; Italian: Trattato del Trianon; Romanian: Tratatul de la Trianon), often referred to in Hungary as the Peace Dictate of Trianon or Dictate of Trianon, was prepared at the Paris Peace Conference. It was signed in the Grand Trianon at Versailles on 4 June 1920, and formally terminated World War I between most of the Allies of World War I and the Kingdom of Hungary.', 1920, 6, 4, NULL, NULL, NULL, 'day', '4 June 1920', 80, 'https://en.wikipedia.org/wiki/Treaty_of_Trianon'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q748490', 'Treznea massacre', 'The Treznea massacre occurred in the village of Treznea, Sălaj in north-western Transylvania on 9 September 1940, in the immediate aftermath of the Second Vienna Award, when Romania ceded Northern Transylvania to Hungary. The massacre was perpetrated by Hungarian Army troops with aid from some locals; 93 ethnic Romanians and Jews were killed.', 1940, 9, 9, NULL, NULL, NULL, 'day', '9 September 1940', 37, 'https://en.wikipedia.org/wiki/Treznea_massacre'),
  ('Q1503007', 'Ip massacre', 'The Ip massacre was the mass killing of around 150 ethnic Romanians by the Royal Hungarian Army on 14 September 1940, in Ipp, (today Ip, Sălaj County), Northern Transylvania, and in nearby locations and surrounding areas. After two Hungarian soldiers died in an accidental explosion in Ip, rumors spread that they had been killed by Romanians, and the killings were committed in response.', 1940, 9, 14, NULL, NULL, NULL, 'day', '14 September 1940', 39, 'https://en.wikipedia.org/wiki/Ip_massacre'),
  ('Q155103', 'Siege of Budapest', 'The Siege of Budapest or Battle of Budapest, was a major battle fought between Soviet and Romanian forces and Hungarian and German forces for the Hungarian capital of Budapest, near the end of World War II. The Budapest Offensive began on October 29 1944, while the siege lasted from December 26 1944 to February 13, 1945. The Soviets began advancing into the suburbs of Pest in November and encircled Budapest on December 26.', 1944, 12, 24, 1945, 2, 13, 'day', '24 December 1944 – 13 February 1945', 70, 'https://en.wikipedia.org/wiki/Siege_of_Budapest'),
  ('Q582953', 'Battle of Debrecen', 'The Battle of Debrecen, called by the Red Army the Debrecen Offensive Operation, was a battle taking place from 6 to 29 October 1944 on the Eastern Front in Hungary during World War II. The offensive was conducted by the 2nd Ukrainian Front under Marshal Rodion Malinovsky. It was opposed by General Maximilian Fretter-Pico''s German Sixth Army (II formation) and the allied Hungarian VII Army Corps of Army Group South Ukraine The German and Hungarian units were forced to retreat some 160 km and opposed the 2nd Ukrainian Front, which had Debrecen as its strategic objective.', 1944, 10, 29, 1944, 10, 28, 'day', '29 October 1944 – 28 October 1944', 64, 'https://en.wikipedia.org/wiki/Battle_of_Debrecen'),
  ('Q717146', 'Budapest offensive', 'The Budapest offensive was the general attack by Soviet and Romanian armies against Hungary and its Axis ally Nazi Germany. The offensive lasted from 29 October 1944 until the fall of Budapest on 13 February 1945.', 1944, 10, 29, 1945, 2, 13, 'day', '29 October 1944 – 13 February 1945', 59, 'https://en.wikipedia.org/wiki/Budapest_offensive'),
  ('Q164348', 'Hungarian Revolution of 1956', 'The Hungarian Revolution of 1956 (23 October – 4 November 1956; Hungarian: 1956-os forradalom), also known as the Hungarian Uprising, was an attempted countrywide revolution against the government of the Hungarian People''s Republic (1949–1989) and the policies caused by the government''s subordination to the Union of Soviet Socialist Republics (USSR). The uprising lasted 15 days before being crushed by Soviet troops on 7 November 1956 (outside of Budapest, firefights lasted until at least 12 November 1956).', 1956, NULL, NULL, 1956, 11, 10, 'year', '1956', 83, 'https://en.wikipedia.org/wiki/Hungarian_Revolution_of_1956'),
  ('Q1221329', 'Hungarian NATO membership referendum, 1997', 'A referendum on joining NATO was held in Hungary on 16 November 1997. The proposal was approved by 85% of voters, with a voter turnout of 49%.', 1997, 11, 16, NULL, NULL, NULL, 'day', '16 November 1997', 39, 'https://en.wikipedia.org/wiki/1997_Hungarian_NATO_membership_referendum'),
  ('Q180834', '2006 protests in Hungary', 'A series of anti-government protests in Hungary began in September 2006, triggered by the release of Hungarian Prime Minister Ferenc Gyurcsány''s leaked private speech in which he confessed that his Hungarian Socialist Party (MSZP) had lied to win the 2006 election, and had done nothing worth mentioning in the previous four years of governing. Most of the events took place in Budapest and other major cities between 17 September and 23 October.', 2006, NULL, NULL, NULL, NULL, NULL, 'year', '2006', 51, 'https://en.wikipedia.org/wiki/2006_protests_in_Hungary'),
  ('Q471700', '2006 Slovak Air Force Antonov An-24 crash', 'On 19 January 2006, an Antonov An-24 aircraft operated by the Slovak Air Force crashed in northern Hungary, near the village of Hejce and town of Telkibánya. The airplane was carrying Slovak peacekeepers from Kosovo.', 2006, 1, 19, NULL, NULL, NULL, 'day', '19 January 2006', 50, 'https://en.wikipedia.org/wiki/2006_Slovak_Air_Force_Antonov_An-24_crash'),
  ('Q871885', '2009 European floods', 'The 2009 European floods were a series of natural disasters that took place in June 2009 in Central Europe. Austria, the Czech Republic, Germany, Hungary, Poland, Romania, Serbia, Slovakia and Turkey were all affected.', 2009, NULL, NULL, NULL, NULL, NULL, 'year', '2009', 37, 'https://en.wikipedia.org/wiki/2009_European_floods'),
  ('Q282940', '2010 Central European floods', 'The 2010 Central European floods were a devastating series of weather events which occurred across several Central European countries during May and June 2010. Poland was the worst affected.', 2010, 5, 14, 2010, 6, 9, 'day', '14 May 2010 – 9 June 2010', 50, 'https://en.wikipedia.org/wiki/2010_Central_European_floods'),
  ('Q13415210', '2013 European floods', 'Extreme flooding in Central Europe began after several days of heavy rain in late May and early June 2013. Flooding and damages primarily affected south and east German states (Thuringia, Saxony, Saxony-Anhalt, Lower Saxony, Bavaria and Baden-Württemberg), western regions of the Czech Republic (Bohemia), and Austria.', 2013, 5, 28, 2013, 6, 5, 'day', '28 May 2013 – 5 June 2013', 53, 'https://en.wikipedia.org/wiki/2013_European_floods'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q18377751', '2014 Hungarian Internet tax protests', 'In late October 2014, anti-government demonstrations were held in Hungary, which were triggered by the government''s announcement of a proposal to include the taxation of Internet usage in the Taxation Law, to be in effect from 2015. The ruling right-wing coalition''s larger party, Fidesz made their proposal public on October 21, which is meant to extend the existing telecommunications tax to Internet usage.', 2014, NULL, NULL, NULL, NULL, NULL, 'year', '2014', 43, 'https://en.wikipedia.org/wiki/2014_Hungarian_Internet_tax_protests'),
  ('Q24045538', '2016 Hungarian migrant quota referendum', 'A referendum related to the European Union''s migrant relocation plans was held in Hungary on 2 October 2016. The referendum was initiated by the government, under the provision of article 8 of the new constitution of 2012.', 2016, 10, 2, NULL, NULL, NULL, 'day', '2 October 2016', 56, 'https://en.wikipedia.org/wiki/2016_Hungarian_migrant_quota_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q110534944', '2022 Hungarian LGBTQ rights referendum', 'A referendum was held in Hungary on 3 April 2022, coinciding with the parliamentary elections. While the overwhelming majority of valid votes were cast as "no" to the four referendum questions, the share of valid votes was below the 50% required for the result to be considered valid and thus the referendum was rejected.', 2022, 4, 3, NULL, NULL, NULL, 'day', '3 April 2022', 51, 'https://en.wikipedia.org/wiki/2022_Hungarian_anti-LGBTQ_referendum');
